const fs = require('fs');

const pkg = JSON.parse(fs.readFileSync('package.json', 'utf8'));
const repositoryUrl =
  typeof pkg.repository === 'string' ? pkg.repository : pkg.repository.url;
const tsString = (value) =>
  `'${JSON.stringify(value).slice(1, -1).replace(/'/g, "\\'")}'`;

const path = 'src/packageInfo.ts';
const contents = [
  '// Generated by scripts/generate-package-info.js. Do not edit.',
  'export const packageInfo = {',
  `  name: ${tsString(pkg.name)},`,
  `  url: ${tsString(repositoryUrl)},`,
  `  version: ${tsString(pkg.version)},`,
  '} as const;',
  '',
].join('\n');

if (process.argv.includes('--check')) {
  if (fs.readFileSync(path, 'utf8') !== contents) {
    throw new Error(
      `${path} is out of date; run node scripts/generate-package-info.js`
    );
  }
} else {
  fs.writeFileSync(path, contents);
}
